using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.API.Data; using RaceDay.API.DTOs; using RaceDay.API.Models;
namespace RaceDay.API.Controllers;
[ApiController,Route("api/enrolments")]
public class EnrolmentsController(RaceDayContext db):ControllerBase
{
 /// <summary>Enrols the authenticated Participant in a category for a published event.</summary>
 [Authorize(Roles="Participant"),HttpPost,ProducesResponseType(StatusCodes.Status201Created),ProducesResponseType(StatusCodes.Status409Conflict),ProducesResponseType(StatusCodes.Status403Forbidden)] public async Task<IActionResult> Enrol(EnrolmentRequest request){var participantId=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var e=await db.Events.FirstOrDefaultAsync(x=>x.EventId==request.EventId);var c=await db.Categories.FirstOrDefaultAsync(x=>x.CategoryId==request.CategoryId&&x.EventId==request.EventId);if(e is null||c is null)return BadRequest(new{message="The event or category does not exist, or the category belongs to another event."});if(e.Status!="Published")return Conflict(new{message="Only published events can be entered."});if(await db.Enrolments.AnyAsync(x=>x.EventId==request.EventId&&x.ParticipantId==participantId))return Conflict(new{message="You are already enrolled in this event."});if(c.MaxParticipants.HasValue&&await db.Enrolments.CountAsync(x=>x.CategoryId==c.CategoryId&&x.Status!="Cancelled")>=c.MaxParticipants.Value)return Conflict(new{message="This category is full."});var enrolment=new Enrolment{EventId=request.EventId,CategoryId=request.CategoryId,ParticipantId=participantId};db.Enrolments.Add(enrolment);await db.SaveChangesAsync();return Created($"/api/enrolments/me",new{enrolment.EnrolmentId,enrolment.EventId,enrolment.CategoryId,enrolment.ParticipantId,enrolment.EnrolmentDate,enrolment.Status});}
 /// <summary>Lists enrolments belonging to the authenticated Participant.</summary>
 [Authorize(Roles="Participant"),HttpGet("me"),ProducesResponseType(StatusCodes.Status200OK)] public async Task<IActionResult> Mine(){var id=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);return Ok(await db.Enrolments.AsNoTracking().Where(x=>x.ParticipantId==id).Include(x=>x.Event).Include(x=>x.Category).Select(x=>new{x.EnrolmentId,x.EventId,eventTitle=x.Event!.Title,x.CategoryId,categoryName=x.Category!.Name,x.EnrolmentDate,x.Status}).ToListAsync());}
 /// <summary>Lists enrolments for an event owned by the authenticated Organiser.</summary>
 [Authorize(Roles="Organiser"),HttpGet("/api/events/{eventId:int}/enrolments"),ProducesResponseType(StatusCodes.Status200OK),ProducesResponseType(StatusCodes.Status403Forbidden)] public async Task<IActionResult> ForEvent(int eventId){var e=await db.Events.FindAsync(eventId);if(e is null)return NotFound();if(e.OrganiserId!=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!))return Forbid();return Ok(await db.Enrolments.AsNoTracking().Where(x=>x.EventId==eventId).Include(x=>x.Participant).Include(x=>x.Category).Select(x=>new{x.EnrolmentId,x.EventId,x.ParticipantId,participantEmail=x.Participant!.Email,participantName=x.Participant.FirstName+" "+x.Participant.LastName,x.CategoryId,categoryName=x.Category!.Name,x.EnrolmentDate,x.Status}).ToListAsync());}
 /// <summary>Updates an enrolment status for an event owned by the authenticated Organiser.</summary>
 [Authorize(Roles="Organiser"),HttpPut("{id:int}/status"),ProducesResponseType(StatusCodes.Status200OK),ProducesResponseType(StatusCodes.Status403Forbidden),ProducesResponseType(StatusCodes.Status404NotFound)] public async Task<IActionResult> UpdateStatus(int id,StatusRequest request){var en=await db.Enrolments.Include(x=>x.Event).FirstOrDefaultAsync(x=>x.EnrolmentId==id);if(en is null)return NotFound();if(en.Event!.OrganiserId!=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!))return Forbid();if(!new[]{"Pending","Confirmed","Cancelled","Completed"}.Contains(request.Status,StringComparer.OrdinalIgnoreCase))return BadRequest(new{message="Invalid enrolment status."});en.Status=request.Status;await db.SaveChangesAsync();return Ok(en);}
}